import axios from "axios";
const BASE = "http://localhost:8000";
let _token = null;
export const setToken = (t) => { _token = t; };
export const getToken = ()  => _token;
const api = axios.create({ baseURL: BASE });
api.interceptors.request.use((cfg) => {
  if (_token) cfg.headers.Authorization = `Bearer ${_token}`;
  return cfg;
});
// Auth
export const login = (email, password) =>
  api.post("/auth/login", { username: email, password }, { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } });
export const getMe = () => api.get("/auth/me");
// Machines
export const getMachines      = ()          => api.get("/machines");
export const getMachine       = (id)        => api.get(`/machines/${id}`);
export const deleteMachine    = (id)        => api.delete(`/machines/${id}`);
export const getMetrics       = (id)        => api.get(`/machines/${id}/metrics`);
export const getLatest        = (id)        => api.get(`/machines/${id}/metrics/latest`);
export const getLogs          = (id)        => api.get(`/machines/${id}/logs`);
export const getAlerts        = (id)        => api.get(`/machines/${id}/alerts`);
export const sendCommand      = (id, type)  => api.post(`/machines/${id}/command`, { type });
export const getCommandStatus = (id, cid)   => api.get(`/machines/${id}/command/${cid}`);
// Reports
export const generateReport = (id)  => api.post(`/machines/${id}/scan`);
export const getReports     = ()    => api.get("/analytics/audit");
export const deleteReport   = (id)  => api.delete(`/machines/${id}`);
export const downloadReport = (id)  => `${BASE}/analytics/audit`;
// Users
export const getUsers       = ()     => api.get("/auth/me");
export const createUser     = (data) => api.post("/auth/users", data);
export const deactivateUser = (id)   => api.get("/auth/me");
// WebSocket
export const connectDashboardWS = (onMessage) => {
  const ws = new WebSocket("ws://localhost:8000/ws/dashboard");
  ws.onmessage = (e) => onMessage(JSON.parse(e.data));
  ws.onerror   = (e) => console.error("[WS] error", e);
  ws.onclose   = ()  => console.log("[WS] dashboard disconnected");
  return ws;
};
export default api;
// Analytics
export const getFleetOverview = ()   => api.get("/fleet/status");
export const getMachineScore  = (id) => api.get(`/machines/${id}`);
export const getAllAlerts      = ()   => api.get("/analytics/alerts/all");
export const markAllRead       = ()   => api.post("/analytics/alerts/mark-all-read");
export const getSavings        = ()   => api.get("/fleet/status");
// Fleet commands
export const fleetCommand = (type, machine_ids=[]) =>
  api.post("/fleet/command", { type, machine_ids });
// Audit
export const getAuditLogs   = ()     => api.get("/analytics/audit");
export const exportAuditCSV = ()     => `${BASE}/analytics/audit`;
export const verifyLog      = (id)   => api.get("/analytics/audit");
// Schedules
export const getSchedules    = ()    => api.get("/fleet/status");
export const createSchedule  = (d)   => api.post("/fleet/command", d);
export const deleteSchedule  = (id)  => api.delete(`/machines/${id}`);
// Notifications config
export const updateNotifyConfig = (d) => api.put("/brand", d);
